const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const roi = ee.Geometry.Polygon([
      [[103.0, 28.0], [108.5, 28.0], [108.5, 32.8], [103.0, 32.8], [103.0, 28.0]]
    ]); // Approximate Sichuan Basin
    const yearA = 2006;
    const yearB = 2020;

    // Helper: detect an AOD band from a dataset
    async function detectAODBand(datasetId, probeYear) {
      const col = ee.ImageCollection(datasetId)
        .filterDate(`${probeYear}-01-01`, `${probeYear + 1}-01-01`);
      const first = col.first();
      const bands = await first.bandNames().getInfo().catch(() => null);
      if (!bands || !bands.length) return null;
      const candidates = [
        'Aerosol_Optical_Depth_Land_Ocean_Mean_Mean',
        'Aerosol_Optical_Depth_Land_Ocean_Mean',
        'Aerosol_Optical_Depth_Mean_Mean'
      ];
      for (const c of candidates) if (bands.includes(c)) return c;
      const generic = bands.find(b => b.includes('Aerosol_Optical_Depth') && b.includes('Mean') && !b.includes('Standard_Deviation'));
      return generic || null;
    }

    // Helper: compute annual stats
    async function getYearStats(datasetId, bandName, year) {
      const col = ee.ImageCollection(datasetId)
        .filterDate(`${year}-01-01`, `${year + 1}-01-01`)
        .select(bandName);
      const size = await col.size().getInfo();
      if ((size || 0) === 0) return { size: 0, count: 0, mean: null };
      const annual = col.mean();
      const result = await annual.reduceRegion({
        reducer: ee.Reducer.combine({ reducer1: ee.Reducer.count(), reducer2: ee.Reducer.mean(), sharedInputs: true }),
        geometry: roi,
        scale: 30000,
        maxPixels: 1e9,
        tileScale: 2
      }).getInfo();
      const count = result[`${bandName}_count`] || 0;
      const mean = result[`${bandName}_mean`];
      return { size, count, mean };
    }

    // 2. Data Acquisition & Check with fallback
    const primaryDataset = 'MODIS/006/MOD08_M3'; // Terra monthly
    const fallbackDataset = 'MODIS/006/MYD08_M3'; // Aqua monthly

    let datasetUsed = primaryDataset;
    let band = await detectAODBand(datasetUsed, yearA);
    if (!band) band = await detectAODBand(datasetUsed, yearB);
    if (!band) {
      datasetUsed = fallbackDataset;
      band = await detectAODBand(datasetUsed, yearA) || await detectAODBand(datasetUsed, yearB);
    }
    if (!band) {
      console.log('Band detection failed.');
      console.log('D');
      return;
    }

    let statsA = await getYearStats(datasetUsed, band, yearA);
    let statsB = await getYearStats(datasetUsed, band, yearB);

    // If empty for either year, try fallback dataset (if not already using it)
    if ((statsA.size === 0 || statsB.size === 0) && datasetUsed !== fallbackDataset) {
      datasetUsed = fallbackDataset;
      band = await detectAODBand(datasetUsed, yearA) || await detectAODBand(datasetUsed, yearB);
      if (!band) {
        console.log(`No images or band not found for ${primaryDataset} and ${fallbackDataset}.`);
        console.log('C1');
        return;
      }
      statsA = await getYearStats(datasetUsed, band, yearA);
      statsB = await getYearStats(datasetUsed, band, yearB);
    }

    if (statsA.size === 0 || statsB.size === 0) {
      console.log(`Empty Collection: ${yearA} Images: ${statsA.size}, ${yearB} Images: ${statsB.size}`);
      console.log('C1');
      return;
    }

    // 3. Processing / Valid pixel checks
    if ((statsA.count || 0) === 0 || (statsB.count || 0) === 0) {
      console.log(`No valid pixels after masking. ${yearA} count: ${statsA.count}, ${yearB} count: ${statsB.count}`);
      console.log('C2');
      return;
    }

    // 4. Calculation and validation
    const meanA = statsA.mean;
    const meanB = statsB.mean;
    if (
      meanA === null || meanB === null ||
      !isFinite(meanA) || !isFinite(meanB) ||
      meanA < 0 || meanB < 0 || meanA > 5 || meanB > 5
    ) {
      console.log(`Invalid result. ${yearA} mean: ${meanA}, ${yearB} mean: ${meanB}`);
      console.log('C3');
      return;
    }

    const delta = meanB - meanA;
    const pct = meanA !== 0 ? (delta / meanA) * 100 : null;

    // 5. Print concise evidence (<=20 lines) and final answer
    console.log(`Dataset: ${datasetUsed}, Band: ${band}`);
    console.log(`${yearA} Images: ${statsA.size}`);
    console.log(`${yearB} Images: ${statsB.size}`);
    console.log(`${yearA} Valid Pixels: ${Math.round(statsA.count)}`);
    console.log(`${yearB} Valid Pixels: ${Math.round(statsB.count)}`);
    console.log(`${yearA} Mean AOD: ${meanA.toFixed(3)}`);
    console.log(`${yearB} Mean AOD: ${meanB.toFixed(3)}`);
    console.log(`Change (2020-2006): ${delta.toFixed(3)} (${pct !== null ? pct.toFixed(1) : 'NA'}%)`);

    // Final decision: A if decreased (meanB < meanA by at least 0.01), else B
    const decreased = (meanB + 0.01) < meanA;
    console.log(decreased ? 'A' : 'B');
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
